export { useCallbackRef } from "./use-callback-ref";
export { useControllableState } from "./use-controllable-state";
export { default as useToast } from "./use-toast";
export { usePagination } from "./use-pagination";
export { ThemeProvider, ThemeContext, useTheme } from "./use-theme";

import * as React from "react";

/**
 * A custom hook that converts a callback to a ref to avoid triggering re-renders when passed as a
 * prop or avoid re-executing effects when passed as a dependency
 */
function useCallbackRef<T extends (...args: any[]) => any>(
  callback: T | undefined,
): T {
  const callbackRef = React.useRef(callback);

  React.useEffect(() => {
    callbackRef.current = callback;
  });

  // https://github.com/facebook/react/issues/19240
  return React.useMemo(
    () => ((...args) => callbackRef.current?.(...args)) as T,
    [],
  );
}

export { useCallbackRef };

import * as React from "react";
import { useCallbackRef } from "./use-callback-ref";

type UseControllableStateParams<T> = {
  prop?: T;
  defaultProp?: T;
  onChange?: (state: T) => void;
};

type SetStateFn<T> = (prevState?: T) => T;

function useControllableState<T>({
  prop,
  defaultProp,
  onChange = () => {},
}: UseControllableStateParams<T>) {
  const [uncontrolledProp, setUncontrolledProp] = useUncontrolledState({
    defaultProp,
    onChange,
  });
  const isControlled = prop !== undefined;
  const value = isControlled ? prop : uncontrolledProp;
  const handleChange = useCallbackRef(onChange);

  const setValue: React.Dispatch<React.SetStateAction<T | undefined>> =
    React.useCallback(
      (nextValue) => {
        if (isControlled) {
          const setter = nextValue as SetStateFn<T>;
          const value =
            typeof nextValue === "function" ? setter(prop) : nextValue;
          if (value !== prop) handleChange(value as T);
        } else {
          setUncontrolledProp(nextValue);
        }
      },
      [isControlled, prop, setUncontrolledProp, handleChange],
    );

  return [value, setValue] as const;
}

function useUncontrolledState<T>({
  defaultProp,
  onChange,
}: Omit<UseControllableStateParams<T>, "prop">) {
  const uncontrolledState = React.useState<T | undefined>(defaultProp);
  const [value] = uncontrolledState;
  const prevValueRef = React.useRef(value);
  const handleChange = useCallbackRef(onChange);

  React.useEffect(() => {
    if (prevValueRef.current !== value) {
      handleChange(value as T);
      prevValueRef.current = value;
    }
  }, [value, prevValueRef, handleChange]);

  return uncontrolledState;
}

export { useControllableState };

interface usePaginationProps {
  count: number; // Total number of items
  limit: number; // Number of items per page
  page: number; // Current page
  maxDisplay?: number;
}

export function usePagination({
  count,
  limit,
  page,
  maxDisplay = 4,
}: usePaginationProps) {
  // Calculate the maximum number of pages
  const max = Math.ceil(count / limit);

  const getVisiblePageNumber = () => {
    if (max <= maxDisplay) return createRange(1, max);

    if (page <= maxDisplay - 1) {
      const ellipsis_start = maxDisplay;
      return [...createRange(1, ellipsis_start), "...", max];
    }

    if (page >= max - (maxDisplay - 1))
      return [1, "...", ...createRange(max - (maxDisplay - 1), max)];

    return [1, "...", ...createMiddlePages(), "...", max];
  };

  const createRange = (start: number, end: number) => {
    return Array.from({ length: end - start + 1 }, (_, i) => i + start);
  };

  const createMiddlePages = () => {
    const mid_start = Math.max(2, page - 1);
    const mid_end = Math.min(page + 1, max - 1);
    return createRange(mid_start, mid_end);
  };

  return {
    visiblePages: getVisiblePageNumber(),
    max,
  };
}

import {
  createContext,
  FunctionComponent,
  ReactNode,
  useContext,
  useState,
} from "react";

interface ThemeContextType {
  theme: string;
  setTheme: (theme: string) => void;
  defaultTheme: string;
}

const ThemeContext = createContext<ThemeContextType>({
  theme: "light",
  setTheme: () => {},
  defaultTheme: "light",
});

interface ThemeProviderProps {
  children: ReactNode;
  defaultTheme?: string;
  storageKey?: string;
}

const ThemeProvider: FunctionComponent<ThemeProviderProps> = ({
  children,
  defaultTheme = "light",
  storageKey = "theme",
}) => {
  const [theme, setTheme] = useState<string>(defaultTheme);
  const _setTheme = (newTheme: string) => {
    document.documentElement.classList.remove(theme);
    document.documentElement.classList.add(newTheme);
    localStorage.setItem(storageKey, newTheme);
    setTheme(newTheme);
  };

  return (
    <ThemeContext.Provider value={{ theme, defaultTheme, setTheme: _setTheme }}>
      {children}
    </ThemeContext.Provider>
  );
};

const useTheme = () => {
  const context = useContext(ThemeContext);
  if (!context) throw new Error("useTheme must be used within a ThemeProvider");
  return context;
};

export { ThemeProvider, ThemeContext, useTheme };

import { useState } from "react";
import { emitter } from "@/lib/myds/utils/events";
import { ToastEvent } from "@/components/ui/toast";
/**
 * useToast Hook
 * @param {Object} initialState - The initial state for the hook.
 * @returns {[state, setState]} - The current state and a function to update the state.
 */
const useToast = () => {
  const [toasts, setToasts] = useState<ToastEvent[]>([]);

  const handleAddToast = (toast: ToastEvent) => {
    setToasts((prev) => [...prev, toast]);
  };

  const subscribe = () => emitter.on("toast.add", handleAddToast);
  const unsubscribe = () => emitter.off("toast.add", handleAddToast);

  const toast = (props: ToastEvent) => {
    emitter.emit("toast.add", props);
  };

  return {
    toasts,
    toast,
    subscribe,
    unsubscribe,
  };
};

export default useToast;

import mitt from "mitt";
import type { ToastEvent } from "@/components/ui/toast";
